  for d in select value from jsonb_array_elements($defs$[{"id":"f2076b15-7790-5323-ae66-ca5b31c5d54b","key":"hh-felt-safety","version":"v1","instrumentLocale":"en","translationVersion":"hh-en-v1","timeframe":"past-7-days","scoringKey":"configured","scoringVersion":"v1","resultVersion":"v1","title":"Feeling Safe in My Body","source":{"title":"Holistic House — Feeling Safe in My Body","status":"original-playful-non-diagnostic-reflection","reviewedAt":"2026-10-08"},"answerScale":{"min":0,"max":4},"responseAnchors":["Not at all","A little","Somewhat","Quite a lot","Very much"],"scoring":{"dimensions":[{"key":"resources.felt_safety.overall","method":"mean","items":["hh-felt-safety.01","hh-felt-safety.02","hh-felt-safety.03","hh-felt-safety.04","hh-felt-safety.05","hh-felt-safety.06"],"min":0,"max":4,"dimensionClass":"resources","sourceConstruct":"Feeling Safe in My Body","direction":"higher-reported-resource"}]},"questions":[{"id":"hh-felt-safety.01","text":"I can notice when my body begins to tense.","required":true,"direction":"higher-reported-resource"},{"id":"hh-felt-safety.02","text":"I know at least one ordinary situation in which I feel physically at ease.","required":true,"direction":"higher-reported-resource"},{"id":"hh-felt-safety.03","text":"I can change my posture or surroundings when I need more comfort.","required":true,"direction":"higher-reported-resource"},{"id":"hh-felt-safety.04","text":"I can recognise a small sign that I am becoming calmer.","required":true,"direction":"higher-reported-resource"},{"id":"hh-felt-safety.05","text":"I feel able to say no to physical contact I do not want.","required":true,"direction":"higher-reported-resource"},{"id":"hh-felt-safety.06","text":"I have a simple grounding action I can choose when overwhelmed.","required":true,"direction":"higher-reported-resource"}],"optionalContext":[],"suggestedRepeatDays":14,"contentHash":"sha256:88fba1c7ff6ca1a26fc368351f5d55cb5b89ad886bcf8fc881b3df2294c7e9ad"},{"id":"d02f69c6-a6b2-5c